SELECT DISTINCT ?game ?gameName ?releaseDate ?score ?dev ?devName WHERE {
  ?game rdf:type vg:VideoGame . ?game vg:gameName ?gameName .
  ?game vg:developedBy ?dv0 . ?dv0 vg:developerName ?dvn0 . FILTER(CONTAINS(LCASE(STR(?dvn0)), "fromsoftware"))
